<template>
<main class="page">
  <header><div><h1>3D打印委托管理</h1><p>智能制造工艺部—智能制造技术室 · 2台拓竹 H2D</p></div><button v-if="pageTab==='orders'" @click="newForm">新建委托</button></header>
  <nav class="main-tabs"><button v-for="t in topTabs" :key="t.key" :class="{on:pageTab===t.key}" @click="switchTop(t.key)"><span>{{t.icon}}</span>{{t.label}}</button></nav>
