    <div class="scroll"><table><thead><tr><th>委托编号</th><th>主题</th><th>委托人/部门</th><th>紧急程度</th><th>状态</th><th>交期</th><th>进度</th><th></th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.request_no}}</td><td>{{r.subject}}</td><td>{{r.applicant}}<small>{{r.department}}</small></td><td>{{r.urgency}}</td><td><i>{{statusText[r.status]}}</i></td><td>{{date(r.promise_date||r.expected_date)}}</td><td>{{r.progress||0}}%</td><td><button class="link" @click="open(r.id)">查看处理</button></td></tr><tr v-if="!rows.length"><td colspan="8" class="empty">暂无数据</td></tr></tbody></table></div>
  </section>
  <section v-if="tab==='form'" class="card">
    <div class="form-heading"><div><h2>{{form.id?'修改委托':'新建委托'}}</h2><p class="muted">默认只需填写基础需求，不懂材料或工艺时可直接选择“由智能室判断”。</p></div><div class="mode-switch"><button :class="{on:!professionalMode}" @click="professionalMode=false">简易模式</button><button :class="{on:professionalMode}" @click="professionalMode=true">专业模式</button></div></div>
    <aside class="rules"><b>委托须知</b><ul><li>仅受理与公司生产、科研、质量改进、培训教学等工作相关的打印任务，不得委托私人玩具、摆件或其他与工作无关的模型。</li><li>委托人须确认模型来源合法，不得上传涉密范围之外传播的文件、侵权模型、违禁品或存在安全风险的结构。</li><li>尺寸、材料和精度以设备能力、现有耗材及技术校核结论为准；复杂模型可能拆分打印或需要修改。</li><li>期望完成时间不是承诺交期，正式交期在审批通过并排期后确定。</li></ul><label class="agree"><input type="checkbox" v-model="rulesAccepted">我已阅读并同意上述委托要求 <span class="required">*</span></label></aside>
    <div class="grid simple-grid">
      <label class="wide">这次想打印什么？ <span class="required">*</span><input v-model="form.subject" placeholder="例如：某项目定位工装、产品外观验证样件"></label>
      <label>审批领导 <span class="required">*</span><select v-model="form.leader_approver"><option value="">请选择</option><option v-for="x in boot.leaders" :key="x.name" :value="x.name">{{x.name}}{{x.title?'（'+x.title+'）':''}}</option></select><small>领导名单由系统管理员配置</small></label>
      <label>主要用途<select v-model="form.purpose"><option v-for="x in purposes" :key="x">{{x}}</option></select></label>
      <label>需要几件？ <span class="required">*</span><input type="number" min="1" v-model.number="form.quantity"></label>
      <label>希望什么时候完成？<input type="date" v-model="form.expected_date"></label>
      <label>紧急程度<select v-model="form.urgency"><option>普通</option><option>紧急</option><option>特急</option></select></label>
      <label>材料<select v-model="form.material"><option value="">由智能室判断</option><option v-for="x in materialOptions" :key="x">{{x}}</option></select></label>
      <label>颜色<select v-model="form.color"><option value="">由智能室判断</option><option v-for="x in colorOptions" :key="x">{{x}}</option></select></label>
      <label class="wide">简单说一下使用场景或想达到的效果<textarea v-model="form.purpose_desc" placeholder="选填。例如：用于装配定位，需要有一定强度；只是看外观尺寸，无特殊强度要求。"></textarea></label>
      <label class="wide">还有什么需要说明？<textarea v-model="form.special_requirement" placeholder="选填。不清楚的内容可以不填，技术人员校核时会与您沟通。"></textarea></label>
    </div>
    <div v-if="professionalMode" class="professional-fields"><div class="professional-tip"><b>专业模式</b><span>以下内容均为选填，不确定时请留空。</span></div><div class="grid"><label>联系方式<input v-model="form.contact"></label><label>项目名称或产品代号<input v-model="form.project_code"></label><label>保密等级<input v-model="form.confidentiality"></label><label>大致尺寸<input v-model="form.approximate_size" placeholder="如 200×100×50 mm"></label><label>强度要求<input v-model="form.strength_requirement"></label><label>表面质量要求<input v-model="form.surface_requirement"></label><label>是否允许拆分打印<select v-model="form.split_policy"><option>允许</option><option>不允许</option><option>由智能室判断</option></select></label><label class="check"><input type="checkbox" v-model="form.need_model_help">需要协助修改模型</label><label class="check"><input type="checkbox" v-model="form.need_post_process">需要后处理</label><label class="wide">备注<textarea v-model="form.remark"></textarea></label></div></div>
    <div class="upload"><label>模型文件 <span class="required">*</span><input ref="modelFiles" type="file" multiple></label><label>其他附件<input ref="auxFiles" type="file" multiple></label><small>支持格式与单文件 {{boot.config.max_file_mb||500}}MB 上限均由管理员配置。</small></div>
    <div class="actions"><button @click="tab='mine';load()">取消</button><button @click="save(false)">保存草稿</button><button class="primary" @click="save(true)">保存并提交</button></div>
  </section>
  <section v-if="tab==='detail'&&detail" class="card">
    <div class="title"><div><h2>{{detail.request_no}} · {{detail.subject}}</h2><p>{{detail.applicant}} / {{detail.department}} · {{statusText[detail.status]}}</p></div><button @click="tab='mine';load()">返回</button></div>
    <div class="summary"><div><b>用途</b>{{detail.purpose||'-'}} / {{detail.purpose_desc||'-'}}</div><div><b>打印需求</b>{{detail.quantity}}件 · {{detail.material||'材料待定'}} · {{detail.color||'颜色待定'}}</div><div><b>审批领导 / 交期</b>{{detail.leader_approver||'-'}} · {{date(detail.promise_date||detail.expected_date)}}</div><div><b>进度</b>{{detail.progress||0}}%</div></div>
    <h3>模型及附件</h3><div class="files"><a v-for="a in detail.attachments" :key="a.id" :href="fileUrl(a.id)" target="_blank">{{a.original_name}} (v{{a.version_no}})</a></div>
    <div v-if="canReview" class="operation"><h3>快捷审核</h3><div class="chips"><button v-for="r in reasons" :key="r" :class="{on:chosen.includes(r)}" @click="toggle(r)">{{r}}</button></div><textarea v-model="opinion" placeholder="通过时可留空；退回或驳回必须说明原因"></textarea><div class="actions"><button class="primary" @click="review('approve')">通过</button><button @click="review('return')">退回修改</button><button class="danger" @click="review('reject')">驳回</button></div></div>
    <div v-if="detail.status==='APPROVED_PENDING_SCHEDULE'&&taskAdmin" class="operation"><h3>打印排期</h3><div class="grid"><label>承办人<input v-model="schedule.assignee"></label><label>打印机<select v-model.number="schedule.printer_id"><option v-for="p in boot.printers" :key="p.id" :value="p.id">{{p.printer_name}}</option></select></label><label>承诺交期<input type="date" v-model="schedule.promise_date"></label><label>计划开始<input type="datetime-local" v-model="schedule.planned_start"></label></div><button class="primary" @click="doSchedule">完成排期</button></div>
    <div v-if="taskAdmin&&printable" class="operation"><h3>打印执行（人工更新）</h3><label>进度<input type="number" min="0" max="100" v-model.number="printing.progress"></label><textarea v-model="printing.detail" placeholder="暂停、异常、失败或完成情况"></textarea><div class="actions"><button v-if="['SCHEDULED','REPRINT_PENDING'].includes(detail.status)" class="primary" @click="command('start')">开始打印</button><button v-if="detail.status==='PRINTING'" @click="command('pause')">暂停</button><button v-if="detail.status==='PAUSED'" @click="command('resume')">恢复</button><button v-if="['PRINTING','PAUSED'].includes(detail.status)" class="danger" @click="command('fail')">打印失败</button><button v-if="detail.status==='PRINT_FAILED'" @click="doReprint">创建重打批次</button><button v-if="detail.status==='PRINTING'" class="primary" @click="command('complete')">打印完成</button><button v-if="detail.status==='PRINT_COMPLETED'" class="primary" @click="command('pickup-ready')">通知领取</button></div></div>
    <div v-if="detail.status==='PENDING_PICKUP'&&(detail.applicant===user||taskAdmin)" class="operation"><h3>成品交付</h3><button class="primary" @click="confirmPickup">确认领取并闭环</button></div>
    <h3>全流程记录</h3><div class="timeline"><article v-for="e in detail.events" :key="e.id"><b>{{e.event_type}}</b><span>{{e.operator}} · {{e.created_at}}</span><p>{{e.detail}}</p></article></div>
  </section>
  </div>

  <section v-if="pageTab==='devices'" class="device-page">
    <div class="machine-intro card"><div><span class="eyebrow">BAMBU LAB H2D</span><h2>双喷嘴专业级 3D 打印能力</h2><p>适合工装夹具、样件验证、科研试验、展示模型与维修备件。设备参数来自拓竹官方技术规格，实际可承接范围以智能制造技术室校核为准。</p></div><div class="specs"><div><b>325×320×325</b><span>单喷嘴成型空间 mm</span></div><div><b>350 ℃</b><span>最高喷嘴温度</span></div><div><b>65 ℃</b><span>主动腔温</span></div><div><b>双喷嘴</b><span>多材料 / 专用支撑</span></div></div></div>
    <div class="device-grid"><article v-for="(p,index) in boot.printers" :key="p.id" class="device-card"><div class="device-head"><div><span class="dot" :class="p.status.toLowerCase()"></span><h3>{{p.printer_name}}</h3></div><i>{{printerText[p.status]||p.status}}</i></div><div class="stream"><img :src="cameraUrl(index)" :alt="`${p.printer_name}实时画面`" @error="streamError[index]=true" @load="streamError[index]=false"><div v-if="streamError[index]" class="stream-error">暂时无法加载监控流<br><small>请确认处于公司局域网且摄像头服务正常</small></div><span>● LIVE · 实时画面</span></div><div v-if="taskAdmin||boot.isAdmin" class="device-edit"><select v-model="p.status"><option v-for="(v,k) in printerText" :key="k" :value="k">{{v}}</option></select><input v-model="p.remark" placeholder="设备备注或维护说明"><button @click="savePrinter(p)">更新状态</button></div></article></div>
    <div class="materials card"><h2>常用耗材与选材参考</h2><div class="material-grid"><div><b>PLA</b><p>易打印、表面效果好，适合展示模型、概念样件和培训模型。</p></div><div><b>PETG</b><p>韧性、耐水性优于普通 PLA，适合一般工装、防护件和功能样件。</p></div><div><b>TPU</b><p>柔性弹性材料，适合缓冲件、软连接和保护套；具体硬度需技术确认。</p></div><div><b>ABS / ASA</b><p>耐热、耐冲击，ASA 更适合户外；打印时需封闭腔体和通风控制。</p></div><div><b>PC / PA</b><p>适合高强度、耐热功能件，对干燥、工艺和尺寸设计要求较高。</p></div><div><b>CF / GF 增强材料</b><p>高刚度耐磨，需硬化钢喷嘴；官方建议含碳纤/玻纤材料优先使用 0.6 mm 硬化钢喷嘴。</p></div></div></div>
  </section>

  <section v-if="pageTab==='config'" class="card config-page">
    <div v-if="!boot.isAdmin" class="empty"><h2>无系统配置权限</h2><p>该页面仅现有 OA 系统管理员可访问。</p></div>
    <template v-else><div class="title"><div><h2>3D打印系统配置</h2><p>角色、附件限制、字典和摄像头地址统一在这里维护，代码中不写死人员。</p></div><button class="primary" @click="saveConfig">保存全部配置</button></div>
      <h3>审批与任务角色</h3><div class="grid"><label>一级审核人员（多人用逗号分隔）<input v-model="roleInputs.FIRST_REVIEWER"></label><label>技术校核人员<input v-model="roleInputs.TECH_REVIEWER"></label><label>审批领导<input v-model="roleInputs.LEADER"></label><label>打印任务管理员<input v-model="roleInputs.TASK_ADMIN"></label></div>
      <h3>文件与业务字典</h3><div class="grid"><label>单文件上限（MB）<input type="number" v-model="configForm.max_file_mb"></label><label>模型格式（逗号分隔）<input v-model="configForm.model_extensions"></label><label class="wide">辅助文件格式<input v-model="configForm.aux_extensions"></label><label class="wide">材料选项<input v-model="configForm.material_options"></label><label class="wide">颜色选项<input v-model="configForm.color_options"></label></div>
      <h3>局域网监控流</h3><div class="grid"><label>1号机视频流<input v-model="configForm.monitor_cam0"></label><label>2号机视频流<input v-model="configForm.monitor_cam1"></label></div>
    </template>
  </section>
</main>
</template>
<script setup>
import {computed,onMounted,reactive,ref} from 'vue';import {useRoute} from 'vue-router';import * as api from '@/api/print3d'
const route=useRoute()
const user=(()=>{try{return JSON.parse(localStorage.getItem('userInfo')||'{}').name||''}catch{return''}})(),boot=reactive({config:{},printers:[],roles:[],leaders:[],isAdmin:false}),pageTab=ref('orders'),tab=ref('mine'),rows=ref([]),detail=ref(),keyword=ref(''),status=ref(''),opinion=ref(''),chosen=ref([]),modelFiles=ref(),auxFiles=ref(),rulesAccepted=ref(false),professionalMode=ref(false),streamError=reactive({})
const statusText={DRAFT:'草稿',PENDING_FIRST_REVIEW:'待一级审核',RETURNED_BY_FIRST_REVIEW:'一级审核退回',PENDING_TECH_REVIEW:'待技术校核',RETURNED_BY_TECH_REVIEW:'技术校核退回',PENDING_LEADER_APPROVAL:'待领导审批',RETURNED_BY_LEADER:'领导退回',REJECTED:'已驳回',APPROVED_PENDING_SCHEDULE:'待排期',SCHEDULED:'已排期',PRINTING:'打印中',PAUSED:'已暂停',PRINT_FAILED:'打印失败',REPRINT_PENDING:'待重新打印',PRINT_COMPLETED:'打印完成',PENDING_PICKUP:'待领取',COMPLETED:'已闭环',CANCELLED:'已取消'},purposes=['工装夹具','样件验证','科研试验','展示模型','维修备件','培训教学','其他'],reasons=['请补充模型文件','请补充用途说明','请补充数量','请补充期望完成时间','请补充打印要求','不属于本部门受理范围','请与智能室沟通','其他']
const fresh=()=>({id:null,subject:'',leader_approver:'',contact:'',expected_date:null,urgency:'普通',purpose:'样件验证',project_code:'',purpose_desc:'',confidentiality:'内部',remark:'',quantity:1,approximate_size:'',material:'',color:'',strength_requirement:'',surface_requirement:'',split_policy:'由智能室判断',need_model_help:false,need_post_process:false,special_requirement:''}),form=reactive(fresh()),schedule=reactive({assignee:'',printer_id:null,promise_date:'',planned_start:null,planned_end:null,note:''}),printing=reactive({progress:0,detail:''})
const staff=computed(()=>boot.roles.some(x=>['FIRST_REVIEWER','TECH_REVIEWER','LEADER','TASK_ADMIN'].includes(x))),topTabs=computed(()=>[{key:'orders',label:'委托单',icon:'▤'},{key:'devices',label:'设备状态',icon:'◉'},...(boot.isAdmin?[{key:'config',label:'系统配置',icon:'⚙'}]:[])]),tabs=computed(()=>[{key:'mine',label:'我的委托'},...(staff.value?[{key:'todo',label:'我的待办'},{key:'all',label:'任务台账'}]:[])]),taskAdmin=computed(()=>boot.roles.includes('TASK_ADMIN')),canReview=computed(()=>detail.value&&((detail.value.status==='PENDING_FIRST_REVIEW'&&boot.roles.includes('FIRST_REVIEWER'))||(detail.value.status==='PENDING_TECH_REVIEW'&&boot.roles.includes('TECH_REVIEWER'))||(detail.value.status==='PENDING_LEADER_APPROVAL'&&boot.roles.includes('LEADER')))),printable=computed(()=>detail.value&&['SCHEDULED','PRINTING','PAUSED','PRINT_FAILED','REPRINT_PENDING','PRINT_COMPLETED'].includes(detail.value.status))
const materialOptions=computed(()=>(boot.config.material_options||'').split(',').map(x=>x.trim()).filter(Boolean)),colorOptions=computed(()=>(boot.config.color_options||'').split(',').map(x=>x.trim()).filter(Boolean)),printerText={IDLE:'空闲',SCHEDULED:'已排期',PRINTING:'打印中',PAUSED:'已暂停',MAINTENANCE:'维护中',OFFLINE:'离线'}
const configForm=reactive({}),roleInputs=reactive({FIRST_REVIEWER:'',TECH_REVIEWER:'',LEADER:'',TASK_ADMIN:''})
const date=x=>x?String(x).slice(0,10):'-',err=e=>alert(e.response?.data?.detail||e.message),newForm=()=>{Object.assign(form,fresh());rulesAccepted.value=false;professionalMode.value=false;tab.value='form'},switchTop=k=>{pageTab.value=k;if(k==='orders')load();if(k==='config')loadConfig()}
async function load(){if(!['mine','todo','all'].includes(tab.value))return;try{rows.value=(await api.listRequests({current_user:user,scope:tab.value,status:status.value,keyword:keyword.value})).data||[]}catch(e){err(e)}}
async function open(id){detail.value=(await api.getRequest(id,user)).data;printing.progress=detail.value.progress||0;tab.value='detail'}
async function upload(id,el,category){if(!el?.files?.length)return;const fd=new FormData();fd.append('current_user',user);fd.append('category',category);[...el.files].forEach(f=>fd.append('files',f));await api.uploadFiles(id,fd)}
async function save(submit){try{if(submit&&!rulesAccepted.value)throw new Error('请先阅读并同意委托要求');const r=await api.saveRequest({...form,rules_accepted:rulesAccepted.value,current_user:user});form.id=r.id;await upload(r.id,modelFiles.value,'MODEL');await upload(r.id,auxFiles.value,'AUX');if(submit)await api.submitRequest(r.id,{current_user:user,action:'submit'});alert(submit?'提交成功':'草稿已保存');tab.value='mine';load()}catch(e){err(e)}}
const toggle=r=>chosen.value=chosen.value.includes(r)?chosen.value.filter(x=>x!==r):[...chosen.value,r]
async function review(action){try{const stage=detail.value.status==='PENDING_FIRST_REVIEW'?'first':detail.value.status==='PENDING_TECH_REVIEW'?'tech':'leader';await api.reviewRequest(detail.value.id,stage,{current_user:user,action,opinion:opinion.value,reason_tags:chosen.value});open(detail.value.id)}catch(e){err(e)}}
async function doSchedule(){try{await api.scheduleRequest(detail.value.id,{...schedule,current_user:user});open(detail.value.id)}catch(e){err(e)}}async function command(c){try{await api.printCommand(detail.value.id,c,{...printing,current_user:user});open(detail.value.id)}catch(e){err(e)}}async function doReprint(){try{await api.reprint(detail.value.id,{...printing,current_user:user});open(detail.value.id)}catch(e){err(e)}}async function confirmPickup(){try{await api.pickup(detail.value.id,{current_user:user,receiver:user,note:'确认领取'});open(detail.value.id)}catch(e){err(e)}}const fileUrl=id=>api.attachmentUrl(id,user)
const cameraUrl=i=>boot.config[`monitor_cam${i}`]||`http://10.42.60.211:8080/cam${i}/stream`
async function savePrinter(p){try{await api.updatePrinter(p.id,{current_user:user,status:p.status,location:p.location||'',remark:p.remark||''});alert('设备状态已更新')}catch(e){err(e)}}
async function loadConfig(){if(!boot.isAdmin)return;try{const r=await api.getAdminConfig(user);Object.assign(configForm,r.config||{});for(const k of Object.keys(roleInputs)){roleInputs[k]=(r.roles||[]).filter(x=>x.role_code===k).map(x=>x.user_name).join('，')}}catch(e){err(e)}}
async function saveConfig(){try{const roles={};for(const [k,v] of Object.entries(roleInputs))roles[k]=v.split(/[,，]/).map(x=>x.trim()).filter(Boolean);await api.saveAdminConfig({current_user:user,config:{...configForm},roles});Object.assign(boot.config,configForm);alert('系统配置已保存')}catch(e){err(e)}}
onMounted(async()=>{try{Object.assign(boot,await api.bootstrap(user));schedule.printer_id=boot.printers[0]?.id;if(route.query.id)await open(Number(route.query.id));else load()}catch(e){err(e)}})
